import type { DocumentKind } from "../enums/document-kind.enum";
import { IpcChannel } from "../enums/ipc-channel.enum";

export type DocumentSummary = {
  id: string;
  kind: DocumentKind;
  /** Order within the same kind, starting at 1 */
  position: number;
  /** Custom title of the user, empty means the default title generated by the UI from kind and position */
  title: string;
};

export type DocumentData = DocumentSummary & { text: string };

export type DocumentContract = {
  [IpcChannel.DocumentList]: { req: void; res: DocumentSummary[] };
  [IpcChannel.DocumentGet]: { req: { id: string }; res: DocumentData };
  [IpcChannel.DocumentSave]: { req: { id: string; text: string }; res: void };
  [IpcChannel.DocumentCreate]: { req: { kind: DocumentKind }; res: DocumentSummary };
  [IpcChannel.DocumentDelete]: { req: { id: string }; res: void };
  /** Moves up by -1 or down by 1 within the same kind, nothing happens at the edge */
  [IpcChannel.DocumentMove]: { req: { id: string; delta: -1 | 1 }; res: void };
  [IpcChannel.DocumentRename]: { req: { id: string; title: string }; res: void };
};
